import"./chunk-7CGTOI24.js";var e={slug:"review-ruptura-severance",title:"Review: Ruptura \xE9 a s\xE9rie mais inquietante sobre trabalho j\xE1 feita",dek:"Duas temporadas depois, a s\xE9rie da Apple TV sobre funcion\xE1rios com mem\xF3rias divididas segue impec\xE1vel. Revisitamos Lumon enquanto esperamos o pr\xF3ximo ano.",section:"series",kind:"review",tags:["Apple TV","Fic\xE7\xE3o cient\xEDfica","Suspense"],date:"2026-10-16",hero:{ref:"tv:95396",pick:0,alt:"Adam Scott como Mark Scout em cena de Ruptura"},score:9,verdict:{summary:"Fic\xE7\xE3o cient\xEDfica que fala do mundo real com humor seco, suspense e um elenco perfeito. A segunda temporada \xE9 mais lenta, mas aprofunda tudo o que importava.",good:["Premissa simples e assustadoramente plaus\xEDvel","Elenco afinado, com destaque para Adam Scott e Britt Lower","Dire\xE7\xE3o de arte que transforma o escrit\xF3rio em personagem"],bad:["Ritmo lento em parte da segunda temporada","Mist\xE9rios que demoram a render respostas"]},body:[{p:"Imagine um procedimento que separa completamente suas mem\xF3rias do trabalho das mem\xF3rias da vida pessoal. No escrit\xF3rio, voc\xEA n\xE3o sabe quem \xE9 l\xE1 fora. L\xE1 fora, voc\xEA n\xE3o faz ideia do que faz no escrit\xF3rio. Essa \xE9 a premissa de *Ruptura*, criada por Dan Erickson para a Apple TV, e talvez a melhor met\xE1fora da TV recente sobre o que o trabalho faz com as pessoas."},{ficha:"tv:95396"},{h2:"Bem-vindos \xE0 Lumon"},{p:"Mark Scout, vivido por Adam Scott, trabalha no departamento de Refinamento de Macrodados da Lumon Industries. Ao lado de Helly R., de Britt Lower, e Dylan, de Zach Cherry, ele passa os dias organizando n\xFAmeros cujo prop\xF3sito ningu\xE9m conhece. A supervis\xE3o fica com Seth Milchick, de Tramell Tillman, e com Harmony Cobel, de Patricia Arquette."},{p:"A s\xE9rie alterna o mundo de dentro, com corredores brancos infinitos e uma cultura corporativa quase religiosa, e o mundo de fora, onde Mark lida com o luto. A tens\xE3o entre essas duas vidas \xE9 o motor de tudo."},{img:"tv:95396",pick:2,caption:"Os corredores da Lumon s\xE3o um dos cen\xE1rios mais marcantes da TV. Imagem de divulga\xE7\xE3o."},{h2:"O que funciona"},{p:"O humor \xE9 seco e desconfort\xE1vel, e o suspense nasce de detalhes: uma festa de recompensa com waffles, um quadro na parede, uma regra sem explica\xE7\xE3o. O elenco \xE9 perfeito. Tramell Tillman transforma Milchick em uma das figuras mais assustadoras e engra\xE7adas da TV, e Britt Lower carrega a temporada com uma personagem que se recusa a aceitar o pr\xF3prio destino."},{quote:"Ruptura acerta porque n\xE3o exagera. A Lumon assusta justamente por parecer um lugar onde algu\xE9m que voc\xEA conhece poderia trabalhar."},{h2:"A segunda temporada"},{p:"Lan\xE7ada em 2025, a segunda temporada \xE9 mais lenta e mais estranha. Alguns epis\xF3dios se afastam do escrit\xF3rio e pedem paci\xEAncia, mas o arco recompensa quem fica. O final reorganiza as pe\xE7as com coragem e deixa a vontade de saber o que vem a seguir. Segundo o TMDB, a s\xE9rie segue em produ\xE7\xE3o."},{h2:"Veredito"},{p:"*Ruptura* \xE9 a s\xE9rie que voc\xEA recomenda para algu\xE9m e depois quer discutir cada epis\xF3dio com essa pessoa. Nota 9."},{p:"Procurando outras s\xE9ries para maratonar? Veja nossa lista de [s\xE9ries completas para o fim de ano](/artigo/series-completas-para-maratonar)."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{},movies:{},tv:{95396:{id:95396,name:"Ruptura",original:"Severance",overview:"Mark lidera uma equipe de funcion\xE1rios de escrit\xF3rio cujas mem\xF3rias foram divididas cirurgicamente entre a vida no trabalho e a vida pessoal. Quando um colega de trabalho misterioso aparece fora do escrit\xF3rio, ele come\xE7a uma jornada para descobrir a verdade sobre seu trabalho.",poster:"/3DjOAUBR8Hra4R9kK9U8jDaoqyC.jpg",backdrops:["/ixgFmf1X59PUZam2qbAfskx2gQr.jpg","/9xDCTGhEWpz206PCiimRGmK67rV.jpg","/r9KaBE7i4ovg8uSppQrCp6ZdPD9.jpg","/npD65vPa4vvn1ZHpp3o05A5vdKT.jpg","/8MtMFngDWvIdRo34rz3ao0BGBAe.jpg"],genres:["Drama","Mist\xE9rio","Sci-Fi & Fantasy"],cert:"16",creators:["Dan Erickson"],cast:[{name:"Adam Scott",role:"Mark Scout"},{name:"Britt Lower",role:"Helly Riggs"},{name:"Tramell Tillman",role:"Seth Milchick"},{name:"Zach Cherry",role:"Dylan George"},{name:"Patricia Arquette",role:"Harmony Cobel"},{name:"Jen Tullock",role:"Devon Scout-Hale"}],networks:["Apple TV"],first:"2022-02-17",last:"2025-03-20",status:"Em produ\xE7\xE3o",seasons:3,episodes:19,next:null,country:"US"}}};export{o as media,e as post};
